// The event loop lets Node do this without blocking:
console.log('1: start');

setTimeout(() => console.log('2: timeout'), 0);

fs.readFile(__filename, () => console.log('3: file read'));

console.log('4: end');

// Output order: 1, 4, 2 or 3 (order between timer/IO varies by context),
// but '1' and '4' always run first — sync code always completes before callbacks.

const fs = require('fs');

fs.readFile(__filename, () => {
  setTimeout(() => console.log('timeout'), 0);
  setImmediate(() => console.log('immediate'));
});
// Inside an I/O callback, 'immediate' always logs before 'timeout' —
// because the check phase (setImmediate) comes right after poll (I/O).

// Blocking — freezes the whole process until the read completes
const data = fs.readFileSync('file.txt');
console.log(data);

// Non-blocking — process continues immediately, callback runs later
fs.readFile('file.txt', (err, data) => {
  console.log(data);
});
console.log('This logs before the file content in the async version');

